package org.brightstats.stats;

import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class ProcessChecks {
    private static int checks;
    private static void check(boolean value){checks++;if(!value)throw new AssertionError("Process check "+checks);}
    private static void close(double a,double b){checks++;if(!Double.isFinite(a)||!Double.isFinite(b)||Math.abs(a-b)>2e-9*Math.max(1,Math.abs(b)))throw new AssertionError("Process "+a+" != "+b);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid process model accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonArray cases=new JsonArray();List<String> names=List.of("X","M1","M2","Y","W","Z","Control");Random random=new Random(20261118);double[][] data=new double[120][7];for(double[] row:data){double x=random.nextGaussian()+1,w=random.nextGaussian()+.4,z=random.nextGaussian()-.3,c=random.nextGaussian(),m1=.3+.6*x+.25*x*w+.4*c+.7*random.nextGaussian(),m2=.2+.3*x+.5*m1+.2*m1*z+.2*c+.7*random.nextGaussian(),y=.4+.2*x+.4*m1+.5*m2+.3*x*w-.15*m2*w+.1*m2*w*z+.15*c+.7*random.nextGaussian();row[0]=x;row[1]=m1;row[2]=m2;row[3]=y;row[4]=w;row[5]=z;row[6]=c;}
        var simple=new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,1),new PathProcess.Path(1,3),new PathProcess.Path(0,3)),new int[]{6});var parallel=new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,1),new PathProcess.Path(0,2),new PathProcess.Path(1,3),new PathProcess.Path(2,3),new PathProcess.Path(0,3)),new int[]{6});var moderated=new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,1,new int[]{4}),new PathProcess.Path(0,2),new PathProcess.Path(1,2,new int[]{5}),new PathProcess.Path(0,3,new int[]{4}),new PathProcess.Path(1,3),new PathProcess.Path(2,3,new int[]{4,5})),new int[]{6});
        for(var model:List.of(simple,parallel,moderated))for(var covariance:new RobustRegression.Covariance[]{RobustRegression.Covariance.CLASSICAL,RobustRegression.Covariance.HC3}){List<PathProcess.Probe> probes=model==moderated?List.of(new PathProcess.Probe("Low W",Map.of(4,-.7,5,.2)),new PathProcess.Probe("High W",Map.of(4,1.3,5,.2))):List.of();PathProcess.Fit raw=null;for(var metric:PathProcess.Metric.values()){
            var options=new PathProcess.Options(metric,covariance,.95,true);var fit=PathProcess.fit(data,names,model,options,probes);check(fit.equations().size()==(model==simple?2:3));check(fit.conditionalPaths().size()==fit.probes().size()*model.paths().size());if(metric==PathProcess.Metric.UNSTANDARDIZED)raw=fit;else{double ratio=1;if(metric==PathProcess.Metric.STANDARDIZED){double mx=Arrays.stream(data).mapToDouble(row->row[0]).average().orElseThrow(),my=Arrays.stream(data).mapToDouble(row->row[3]).average().orElseThrow();double vx=0,vy=0;for(double[] row:data){vx+=Math.pow(row[0]-mx,2);vy+=Math.pow(row[3]-my,2);}ratio=Math.sqrt(vx/vy);}for(int j=0;j<fit.effects().size();j++)close(fit.effects().get(j).value(),raw.effects().get(j).value()*ratio);}
            for(var probe:fit.probes()){double gradient=(PathProcess.predict(fit,probe,1.0001)-PathProcess.predict(fit,probe,.9999))/.0002;double total=fit.effects().stream().filter(effect->effect.probe().equals(probe.name())&&effect.family().equals("Total")).findFirst().orElseThrow().value();close(gradient,total*fit.scales()[3]/fit.scales()[0]);}
            JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(data));test.add("names",gson.toJsonTree(names));test.add("model",gson.toJsonTree(model));test.add("options",gson.toJsonTree(options));test.add("probes",gson.toJsonTree(probes));test.add("result",gson.toJsonTree(fit));if(covariance==RobustRegression.Covariance.CLASSICAL&&metric==PathProcess.Metric.UNSTANDARDIZED){var bootstrap=new Bootstrap.Options(40,42,.95,BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true);var inference=PathProcess.bootstrap(data,names,model,options,probes,bootstrap,null);check(inference.inference().successful()==40);test.add("bootstrapOptions",gson.toJsonTree(bootstrap));test.add("bootstrap",gson.toJsonTree(inference.inference()));}cases.add(test);
        }}
        for(int extra=0;extra<3;extra++){var model=extra==0?moderated:extra==1?simple:new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,1),new PathProcess.Path(1,3)),new int[]{6});var settings=new PathProcess.Options(extra==0?PathProcess.Metric.STANDARDIZED:extra==1?PathProcess.Metric.MEAN_CENTERED:PathProcess.Metric.UNSTANDARDIZED,RobustRegression.Covariance.HC3,.95,true);var bootstrap=new Bootstrap.Options(40,295948,.90,extra==0?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE,extra==2?RegressionBootstrap.Convention.REFERENCE_4_1_2_1:RegressionBootstrap.Convention.STANDARD,true);var fitted=PathProcess.bootstrap(data,names,model,settings,List.of(),bootstrap,null);check(fitted.inference().successful()==40);if(extra==2)check(fitted.inference().estimates().stream().filter(estimate->estimate.parameter().family().equals("Direct")).allMatch(estimate->Double.isNaN(estimate.pValue())));if(extra==1)check(fitted.inference().estimates().stream().filter(estimate->estimate.parameter().family().equals("Process coefficient")&&estimate.parameter().column()==0).allMatch(estimate->Double.isNaN(estimate.pValue())));JsonObject test=new JsonObject();test.add("observations",gson.toJsonTree(data));test.add("names",gson.toJsonTree(names));test.add("model",gson.toJsonTree(model));test.add("options",gson.toJsonTree(settings));test.add("probes",gson.toJsonTree(List.of()));test.add("result",gson.toJsonTree(fitted.point()));test.add("bootstrapOptions",gson.toJsonTree(bootstrap));test.add("bootstrap",gson.toJsonTree(fitted.inference()));cases.add(test);}
        var options=PathProcess.Options.defaults();var point=PathProcess.fit(data,names,moderated,options,List.of());check(point.probes().get(0).values().size()==2);var withoutControls=PathProcess.fit(data,names,simple,new PathProcess.Options(PathProcess.Metric.UNSTANDARDIZED,RobustRegression.Covariance.CLASSICAL,.95,false),List.of());check(withoutControls.equations().stream().noneMatch(equation->equation.predictors().stream().anyMatch(term->Arrays.stream(term.columns()).anyMatch(column->column==6))));
        reject(()->PathProcess.fit(data,names,new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,1),new PathProcess.Path(1,0),new PathProcess.Path(1,3)),new int[0]),options,List.of()));reject(()->PathProcess.fit(data,names,new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,1),new PathProcess.Path(1,3,new int[]{1})),new int[0]),options,List.of()));reject(()->PathProcess.fit(data,names,simple,options,List.of(new PathProcess.Probe("Unknown",Map.of(5,1.0)))));reject(()->PathProcess.fit(data,names,new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,1)),new int[0]),options,List.of()));reject(()->PathProcess.fit(data,names,new PathProcess.Model(0,3,List.of(new PathProcess.Path(0,1),new PathProcess.Path(1,3)),new int[]{1}),options,List.of()));
        Thread.currentThread().interrupt();try{PathProcess.fit(data,names,simple,options,List.of());throw new AssertionError("Process ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"process_cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
